// 可复现的伪随机干扰项：故意与查询共享“部署/数据库/日志/依赖”等词。
function rng(seed) {
  let s = seed
  return () => (s = (s * 1664525 + 1013904223) >>> 0) / 2 ** 32
}
export function distractors(count) {
  const r = rng(42)
  const pick = (list) => list[Math.floor(r() * list.length)]
  const mods = [
    '支付',
    '订单',
    '用户中心',
    '搜索',
    '推送',
    '报表',
    '配置中心',
    '缓存',
    '消息队列',
    '权限',
    '网关',
    '风控',
  ]
  const asps = [
    '接口',
    '部署',
    '测试',
    '依赖',
    '数据库',
    '发布',
    '超时',
    '日志',
    '缓存',
    '配置',
    '监控',
    '告警',
  ]
  const acts = [
    '需要先检查再继续',
    '有一个已知问题等待处理',
    '上次调整后暂时稳定',
    '由另一个小组负责维护',
    '文档还没有更新',
    '后续计划再重构一次',
  ]
  const enMods = [
    'billing',
    'auth',
    'search',
    'notification',
    'analytics',
    'gateway',
    'scheduler',
    'storage',
  ]
  const enAsps = [
    'deployment',
    'database',
    'logging',
    'config',
    'retry policy',
    'timeout',
    'dependency',
    'release',
  ]
  const out = []
  for (let i = 0; i < count; i += 1) {
    const zh = r() < 0.75
    const mod = zh ? pick(mods) : pick(enMods)
    const asp = zh ? pick(asps) : pick(enAsps)
    out.push({
      key: `d${i}`,
      title: zh ? `${mod}${asp}备注${i}` : `${mod} ${asp} note ${i}`,
      content: zh
        ? `${mod}模块的${asp}说明：第 ${i} 项${pick(acts)}`
        : `The ${mod} service ${asp} item ${i} is owned by another team and was adjusted recently`,
      type: pick(['fact', 'decision', 'risk', 'task']),
      daysAgo: Math.floor(r() * 400) + 1,
      importance: 0.3 + r() * 0.6,
      exp: '',
    })
  }
  return out
}

export const targetRows = targets.map(([key, title, content, type, daysAgo, exp]) => ({
  key,
  title,
  content,
  type,
  daysAgo,
  importance: 0.5,
  exp,
}))
